{
  "interpretation": {
    "name": "TightenVariantFastenersLine3",
    "scope": {"line": 3, "station": "st3", "tool": "NR7", "variant": "F35"},
    "goal": "Tighten the fasteners of variant F35 at station st3 of line 3 with the shared nutrunner NR7, then evaluate and record the result.",
    "constraints": [
      "Reserve the shared tool NR7 before any use and release it at the end",
      "The tool must be transported to st3 (completed) before configure-tool and tighten-fasteners",
      "Transport-tool Steps are delegated to the Executor agvexecutor",
      "The tightening program comes only from get-program; no numeric process values appear in the Recipe",
      "Every tool-using Step renews the lease with the reservation token, so it depends on reserve-tool",
      "The tightening must be evaluated against its program and recorded for traceability"
    ],
    "preference": "Return the shared tool to the crib after use so that other lines can obtain it.",
    "priority": "normal",
    "horizon": "Single execution for the current request",
    "requested_capabilities": [],
    "omit_services": []
  },
  "recipe": {
    "name": "tighten-line3-f35-with-nr7",
    "first_action": "prepare",
    "actions": [
      {
        "name": "prepare",
        "next": "bring-tool",
        "steps": [
          {
            "name": "reserve",
            "service": "reserve-tool",
            "next": [],
            "dep": [],
            "executor": null,
            "params": {}
          },
          {
            "name": "program",
            "service": "get-program",
            "next": [],
            "dep": [],
            "executor": null,
            "params": {}
          }
        ]
      },
      {
        "name": "bring-tool",
        "next": "tighten",
        "steps": [
          {
            "name": "transport-to-station",
            "service": "transport-tool",
            "next": [],
            "dep": ["reserve"],
            "executor": "agvexecutor",
            "params": {"to": "station"}
          }
        ]
      },
      {
        "name": "tighten",
        "next": "evaluate-and-return",
        "steps": [
          {
            "name": "configure",
            "service": "configure-tool",
            "next": ["tighten-bolts"],
            "dep": ["program", "reserve", "transport-to-station"],
            "executor": null,
            "params": {}
          },
          {
            "name": "tighten-bolts",
            "service": "tighten-fasteners",
            "next": [],
            "dep": ["configure", "reserve", "transport-to-station"],
            "executor": null,
            "params": {}
          }
        ]
      },
      {
        "name": "evaluate-and-return",
        "next": "finish",
        "steps": [
          {
            "name": "evaluate",
            "service": "evaluate-tightening",
            "next": [],
            "dep": ["tighten-bolts", "program"],
            "executor": null,
            "params": {}
          },
          {
            "name": "record",
            "service": "record-tightening",
            "next": [],
            "dep": ["tighten-bolts"],
            "executor": null,
            "params": {}
          },
          {
            "name": "transport-to-crib",
            "service": "transport-tool",
            "next": [],
            "dep": ["reserve", "tighten-bolts"],
            "executor": "agvexecutor",
            "params": {"to": "crib"}
          }
        ]
      },
      {
        "name": "finish",
        "next": null,
        "steps": [
          {
            "name": "release",
            "service": "release-tool",
            "next": [],
            "dep": ["reserve"],
            "executor": null,
            "params": {}
          }
        ]
      }
    ]
  }
}
